package org.apache.lucene.geo;

import static org.apache.lucene.geo.XYEncodingUtils.checkVal;

/**
 * Represents a point on the earth's surface. You can construct the point directly with {@code
 * double} coordinates.
 *
 * <p>NOTES:
 *
 * <ol>
 *   <li>latitude/longitude values must be in decimal degrees.
 *   <li>For more advanced GeoSpatial indexing and query operations see the {@code spatial-extras}
 *       module
 * </ol>
 */
public final class XYPoint extends XYGeometry {

  /** latitude coordinate */
  private final float x;

  /** longitude coordinate */
  private final float y;

  /** Creates a new Point from the supplied latitude/longitude. */
  public XYPoint(float x, float y) {
    this.x = checkVal(x);
    this.y = checkVal(y);
  }

  /** Returns latitude value at given index */
  public float getX() {
    return x;
  }

  /** Returns longitude value at given index */
  public float getY() {
    return y;
  }

  @Override
  protected Component2D toComponent2D() {
    return Point2D.create(this);
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if (!(o instanceof XYPoint)) {
      return false;
    }
    XYPoint point = (XYPoint) o;
    float otherX = point.x;
    float otherY = point.y;

    int thisXEncoded = XYEncodingUtils.encode(x);
    int thisYEncoded = XYEncodingUtils.encode(y);
    int otherXEncoded = XYEncodingUtils.encode(otherX);
    int otherYEncoded = XYEncodingUtils.encode(otherY);

    byte[] thisPacked = new byte[8];
    byte[] otherPacked = new byte[8];
    int thisXSortable = thisXEncoded ^ 0x80000000;
    int thisYSortable = thisYEncoded ^ 0x80000000;
    int otherXSortable = otherXEncoded ^ 0x80000000;
    int otherYSortable = otherYEncoded ^ 0x80000000;
    thisPacked[0] = (byte) (thisXSortable >> 24);
    thisPacked[1] = (byte) (thisXSortable >> 16);
    thisPacked[2] = (byte) (thisXSortable >> 8);
    thisPacked[3] = (byte) thisXSortable;
    thisPacked[4] = (byte) (thisYSortable >> 24);
    thisPacked[5] = (byte) (thisYSortable >> 16);
    thisPacked[6] = (byte) (thisYSortable >> 8);
    thisPacked[7] = (byte) thisYSortable;
    otherPacked[0] = (byte) (otherXSortable >> 24);
    otherPacked[1] = (byte) (otherXSortable >> 16);
    otherPacked[2] = (byte) (otherXSortable >> 8);
    otherPacked[3] = (byte) otherXSortable;
    otherPacked[4] = (byte) (otherYSortable >> 24);
    otherPacked[5] = (byte) (otherYSortable >> 16);
    otherPacked[6] = (byte) (otherYSortable >> 8);
    otherPacked[7] = (byte) otherYSortable;

    boolean packedEqual = true;
    for (int i = 0; i < 8; i++) {
      if (thisPacked[i] != otherPacked[i]) {
        packedEqual = false;
        break;
      }
    }

    float decodedThisX = XYEncodingUtils.decode(thisXEncoded);
    float decodedThisY = XYEncodingUtils.decode(thisYEncoded);
    float decodedOtherX = XYEncodingUtils.decode(otherXEncoded);
    float decodedOtherY = XYEncodingUtils.decode(otherYEncoded);

    if (packedEqual) {
      if (thisXEncoded == otherXEncoded) {
        if (thisYEncoded == otherYEncoded) {
          return decodedThisX == x && decodedThisY == y;
        }
      }
    }

    Component2D thisComponent = Point2D.create(this);
    Component2D otherComponent = Point2D.create(point);
    double thisMinX = thisComponent.getMinX();
    double thisMaxX = thisComponent.getMaxX();
    double thisMinY = thisComponent.getMinY();
    double thisMaxY = thisComponent.getMaxY();
    double otherMinX = otherComponent.getMinX();
    double otherMaxX = otherComponent.getMaxX();
    double otherMinY = otherComponent.getMinY();
    double otherMaxY = otherComponent.getMaxY();

    boolean spatiallyCoincident = false;
    if (decodedOtherX >= thisMinX) {
      if (decodedOtherX <= thisMaxX) {
        if (decodedOtherY >= thisMinY) {
          if (decodedOtherY <= thisMaxY) {
            spatiallyCoincident = thisComponent.contains(decodedOtherX, decodedOtherY);
          }
        }
      }
    }
    if (spatiallyCoincident) {
      spatiallyCoincident = otherComponent.contains(decodedThisX, decodedThisY);
    }
    if (spatiallyCoincident == false) {
      spatiallyCoincident =
          thisComponent.relate(otherMinX, otherMaxX, otherMinY, otherMaxY)
              == otherComponent.relate(otherMinX, otherMaxX, otherMinY, otherMaxY);
    }
    if (spatiallyCoincident == false) {
      boolean collinearLine =
          thisComponent.intersectsLine(
              decodedThisX, decodedThisY, decodedOtherX, decodedOtherY);
      if (collinearLine) {
        spatiallyCoincident = thisComponent.contains(decodedOtherX, decodedOtherY);
      }
    }
    if (spatiallyCoincident == false) {
      return false;
    }
    return x == otherX && y == otherY;
  }

  @Override
  public int hashCode() {
    int result = Float.hashCode(x);
    result = 31 * result + Float.hashCode(y);
    return result;
  }

  @Override
  public String toString() {
    StringBuilder sb = new StringBuilder();
    sb.append("Point(");
    sb.append(x);
    sb.append(",");
    sb.append(y);
    sb.append(')');
    return sb.toString();
  }
}

